import 'dart:convert';

import 'package:bringo/core/constant/app_colors.dart';
import 'package:bringo/core/services/home_service.dart';
import 'package:bringo/features/cart/cart_manager.dart';
import 'package:bringo/features/cart/cart_screen.dart';
import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';

class StoreProductsScreen extends StatefulWidget {
  final Map<String, dynamic> store;
  const StoreProductsScreen({super.key, required this.store});
  @override State<StoreProductsScreen> createState() => _StoreProductsScreenState();
}

class _StoreProductsScreenState extends State<StoreProductsScreen> {
  final TextEditingController searchController = TextEditingController();
  final HomeService _homeService = HomeService();
  String selectedCategory = 'all';
  String searchQuery = '';
  int _productLimit = 30;

  String get storeId { final id = widget.store['id']?.toString().trim() ?? ''; return id.isNotEmpty ? id : widget.store['firebaseKey']?.toString() ?? ''; }
  String get storeName => widget.store['name']?.toString().trim().isNotEmpty == true ? widget.store['name'].toString() : 'المتجر';
  bool get isStoreOpen => widget.store['isOpen'] != false;
  Map<String,dynamic> _productWithStore(Map<String,dynamic> p)=>{...p,'storeId':storeId,'storeName':storeName,'storeType':widget.store['type']?.toString().trim()??''};

  void _addToCart(Map<String,dynamic> product){ if(!isStoreOpen){_message('المتجر مغلق حاليًا');return;} final prepared=_productWithStore(product); if(!CartManager.canAddProduct(prepared)){_showDifferentStoreDialog(prepared);return;} if(!CartManager.addProduct(prepared,1))_message('تعذر إضافة المنتج للسلة'); }
  Future<void> _showDifferentStoreDialog(Map<String,dynamic> product) async { final currentStore=CartManager.storeName.trim(); final replace=await showDialog<bool>(context:context,builder:(c)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20.r)),title:const Text('منتجات من متجر آخر',textAlign:TextAlign.right),content:Text(currentStore.isEmpty?'السلة تحتوي على منتجات من متجر آخر. هل تريد إفراغ السلة وإضافة هذا المنتج؟':'السلة تحتوي على منتجات من $currentStore. هل تريد إفراغ السلة وبدء طلب جديد من $storeName؟',textAlign:TextAlign.right),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:AppColors.primary,foregroundColor:Colors.white),onPressed:()=>Navigator.pop(c,true),child:const Text('إفراغ السلة'))]))); if(replace!=true)return; CartManager.clear(); CartManager.addProduct(product,1); }
  void _message(String m){ScaffoldMessenger.of(context)..hideCurrentSnackBar()..showSnackBar(SnackBar(content:Text(m,textAlign:TextAlign.right),backgroundColor:AppColors.primary,behavior:SnackBarBehavior.floating));}
  void _openCart()=>Navigator.of(context).push(MaterialPageRoute(builder:(_)=>const CartScreen()));

  String _categoryName(Map<String,dynamic> p){final v=p['categoryName']?.toString().trim()??p['menuCategoryName']?.toString().trim()??p['sectionName']?.toString().trim()??'';return v.isEmpty?'منتجات متنوعة':v;}
  String _categoryId(Map<String,dynamic> p){final id=p['categoryId']?.toString().trim()??'';return id.isNotEmpty?id:_categoryName(p).toLowerCase().replaceAll(RegExp(r'\s+'),'_');}
  List<_ProductCategory> _categories(List<Map<String,dynamic>> products){final result=<String,_ProductCategory>{};for(final p in products){final id=_categoryId(p);result.putIfAbsent(id,()=>_ProductCategory(id:id,name:_categoryName(p),image:p['image']?.toString()??''));}return [_ProductCategory(id:'all',name:'الكل',image:widget.store['image']?.toString()??''),...result.values];}
  List<Map<String,dynamic>> _filterProducts(List<Map<String,dynamic>> products){var result=[...products];if(selectedCategory!='all')result=result.where((p)=>_categoryId(p)==selectedCategory).toList();final q=searchQuery.trim().toLowerCase();if(q.isNotEmpty)result=result.where((p)=>(p['name']?.toString().toLowerCase()??'').contains(q)||(p['brand']?.toString().toLowerCase()??'').contains(q)).toList();return result;}
  @override void dispose(){searchController.dispose();super.dispose();}

  @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(backgroundColor:AppColors.background,body:SafeArea(child:Stack(children:[
    StreamBuilder<List<Map<String,dynamic>>>(stream:_homeService.getStoreProducts(storeId,limit:_productLimit),builder:(context,snapshot){
      if(snapshot.connectionState==ConnectionState.waiting&&!snapshot.hasData)return Column(children:[_appBar(),const Expanded(child:Center(child:CircularProgressIndicator(color:AppColors.primary)))]);
      if(snapshot.hasError)return Column(children:[_appBar(),Expanded(child:Center(child:Text('تعذر تحميل المنتجات',style:TextStyle(color:AppColors.textSecondary,fontSize:13.sp))))]);
      final allProducts=snapshot.data??const <Map<String,dynamic>>[];final categories=_categories(allProducts);final products=_filterProducts(allProducts);final canLoadMore=allProducts.length>=_productLimit;
      return CustomScrollView(physics:const BouncingScrollPhysics(),slivers:[SliverToBoxAdapter(child:_appBar()),SliverToBoxAdapter(child:_storeInformation()),SliverToBoxAdapter(child:_searchBox()),SliverToBoxAdapter(child:_categoriesList(categories)),SliverToBoxAdapter(child:Padding(padding:EdgeInsets.fromLTRB(16.w,17.h,16.w,11.h),child:Row(children:[Text(selectedCategory=='all'?'كل المنتجات':categories.firstWhere((c)=>c.id==selectedCategory,orElse:()=>const _ProductCategory(id:'all',name:'المنتجات',image:'')).name,style:TextStyle(color:AppColors.dark,fontSize:18.sp,fontWeight:FontWeight.w900)),SizedBox(width:7.w),Container(padding:EdgeInsets.symmetric(horizontal:8.w,vertical:3.h),decoration:BoxDecoration(color:AppColors.primaryLight,borderRadius:BorderRadius.circular(20.r)),child:Text('${products.length}',style:TextStyle(color:AppColors.primary,fontSize:10.sp,fontWeight:FontWeight.w900)))]))),if(products.isEmpty)SliverToBoxAdapter(child:_emptyProducts())else SliverPadding(padding:EdgeInsets.fromLTRB(16.w,0,16.w,16.h),sliver:SliverList(delegate:SliverChildBuilderDelegate((_,i)=>Padding(padding:EdgeInsets.only(bottom:10.h),child:_StoreProductCard(product:products[i],storeOpen:isStoreOpen,onTap:()=>_addToCart(products[i]),onAdd:()=>_addToCart(products[i]))),childCount:products.length))),if(canLoadMore)SliverToBoxAdapter(child:Padding(padding:EdgeInsets.fromLTRB(16.w,4.h,16.w,145.h),child:OutlinedButton.icon(onPressed:()=>setState(()=>_productLimit+=30),icon:const Icon(Icons.expand_more_rounded),label:const Text('عرض منتجات أكتر'),style:OutlinedButton.styleFrom(foregroundColor:AppColors.primary,side:const BorderSide(color:AppColors.primary),padding:EdgeInsets.symmetric(vertical:13.h),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14.r))))))else SliverToBoxAdapter(child:SizedBox(height:145.h))]);
    }),
    Positioned(left:0,right:0,bottom:0,child:ValueListenableBuilder<List<Map<String,dynamic>>>(valueListenable:CartManager.cartNotifier,builder:(_,items,__)=>(items.isEmpty)?const SizedBox.shrink():_CartBar(items:items,onTap:_openCart)))
  ])))));

  Widget _appBar()=>Container(height:58.h,padding:EdgeInsets.symmetric(horizontal:12.w),decoration:const BoxDecoration(color:Colors.white,border:Border(bottom:BorderSide(color:AppColors.border))),child:Row(children:[_topButton(icon:Icons.arrow_back_ios_new_rounded,onTap:()=>Navigator.pop(context)),Expanded(child:Text(storeName,textAlign:TextAlign.center,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:AppColors.dark,fontSize:17.sp,fontWeight:FontWeight.w900))),SizedBox(width:40.w)]));
  Widget _topButton({required IconData icon,required VoidCallback onTap})=>InkWell(onTap:onTap,borderRadius:BorderRadius.circular(12.r),child:Container(width:40.w,height:40.w,decoration:BoxDecoration(color:AppColors.lightGrey,borderRadius:BorderRadius.circular(12.r)),child:Icon(icon,color:AppColors.dark,size:19.sp)));
  Widget _storeInformation(){final logo=widget.store['image']?.toString()??'';final cover=widget.store['coverImage']?.toString()??'';final rating=widget.store['rating']?.toString()??'4.5';final deliveryTime=widget.store['deliveryTime']?.toString()??'25 - 35 دقيقة';final deliveryFee=widget.store['deliveryFee']?.toString()??'';final tags=widget.store['tags']?.toString()??'';return Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(cover.trim().isNotEmpty)SizedBox(height:130.h,width:double.infinity,child:_SmartImage(image:cover)),Container(color:Colors.white,padding:EdgeInsets.fromLTRB(16.w,14.h,16.w,15.h),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:72.w,height:72.w,padding:EdgeInsets.all(3.w),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(16.r),border:Border.all(color:AppColors.border)),child:ClipRRect(borderRadius:BorderRadius.circular(13.r),child:_SmartImage(image:logo))),SizedBox(width:12.w),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(storeName,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:AppColors.dark,fontSize:17.sp,fontWeight:FontWeight.w900))),Text(isStoreOpen?'مفتوح':'مغلق',style:TextStyle(color:isStoreOpen?const Color(0xFF168547):const Color(0xFFD73A3A),fontWeight:FontWeight.w900))]),if(tags.trim().isNotEmpty)Text(tags,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:AppColors.textSecondary,fontSize:10.5.sp)),SizedBox(height:10.h),Wrap(spacing:12.w,children:[_storeMeta(Icons.star_rounded,rating),_storeMeta(Icons.access_time_rounded,deliveryTime),if(deliveryFee.trim().isNotEmpty)_storeMeta(Icons.delivery_dining_rounded,'$deliveryFee جنيه')])]))])),Container(height:8.h,color:AppColors.background)]);}
  Widget _storeMeta(IconData i,String t)=>Row(mainAxisSize:MainAxisSize.min,children:[Icon(i,size:15.sp,color:AppColors.textSecondary),SizedBox(width:4.w),Text(t,style:TextStyle(color:AppColors.textSecondary,fontSize:10.sp,fontWeight:FontWeight.w700))]);
  Widget _searchBox()=>Container(color:Colors.white,padding:EdgeInsets.fromLTRB(16.w,13.h,16.w,11.h),child:TextField(controller:searchController,onChanged:(v)=>setState(()=>searchQuery=v),textDirection:TextDirection.rtl,decoration:InputDecoration(hintText:'دور على منتج في $storeName',prefixIcon:const Icon(Icons.search_rounded),filled:true,fillColor:AppColors.lightGrey,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14.r),borderSide:BorderSide.none))));
  Widget _categoriesList(List<_ProductCategory> categories)=>Container(color:Colors.white,height:100.h,child:ListView.separated(padding:EdgeInsets.fromLTRB(16.w,6.h,16.w,12.h),scrollDirection:Axis.horizontal,itemCount:categories.length,separatorBuilder:(_,__)=>SizedBox(width:12.w),itemBuilder:(_,i){final c=categories[i];final selected=selectedCategory==c.id;return InkWell(onTap:()=>setState(()=>selectedCategory=c.id),child:SizedBox(width:62.w,child:Column(children:[Container(width:52.w,height:52.w,padding:EdgeInsets.all(7.w),decoration:BoxDecoration(color:selected?AppColors.primaryLight:AppColors.lightGrey,borderRadius:BorderRadius.circular(14.r),border:Border.all(color:selected?AppColors.primary:AppColors.border)),child:c.id=='all'?const Icon(Icons.grid_view_rounded,color:AppColors.primary):ClipRRect(borderRadius:BorderRadius.circular(9.r),child:_SmartImage(image:c.image))),SizedBox(height:5.h),Text(c.name,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:selected?AppColors.primary:AppColors.textSecondary,fontSize:9.sp,fontWeight:FontWeight.w700))]))); }));
  Widget _emptyProducts()=>Padding(padding:EdgeInsets.symmetric(vertical:60.h),child:Center(child:Text('مفيش منتجات مطابقة دلوقتي',style:TextStyle(color:AppColors.dark,fontSize:15.sp,fontWeight:FontWeight.w900))));
}

class _ProductCategory{final String id,name,image;const _ProductCategory({required this.id,required this.name,required this.image});}
class _StoreProductCard extends StatelessWidget{final Map<String,dynamic> product;final bool storeOpen;final VoidCallback onTap,onAdd;const _StoreProductCard({required this.product,required this.storeOpen,required this.onTap,required this.onAdd});@override Widget build(BuildContext context){final name=product['name']?.toString()??'منتج';final image=product['image']?.toString()??'';final price=double.tryParse(product['price']?.toString()??'0')??0;return Material(color:Colors.white,borderRadius:BorderRadius.circular(16.r),child:InkWell(onTap:onTap,child:Container(padding:EdgeInsets.all(10.w),decoration:BoxDecoration(borderRadius:BorderRadius.circular(16.r),border:Border.all(color:AppColors.border)),child:Row(children:[SizedBox(width:86.w,height:86.w,child:ClipRRect(borderRadius:BorderRadius.circular(13.r),child:_SmartImage(image:image))),SizedBox(width:12.w),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(name,maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(color:AppColors.dark,fontSize:14.sp,fontWeight:FontWeight.w900)),SizedBox(height:12.h),Row(children:[Text('${price.toStringAsFixed(price.truncateToDouble()==price?0:2)} جنيه',style:TextStyle(color:AppColors.primary,fontSize:13.sp,fontWeight:FontWeight.w900)),const Spacer(),InkWell(onTap:storeOpen?onAdd:null,child:Container(width:34.w,height:34.w,decoration:BoxDecoration(color:storeOpen?AppColors.primary:AppColors.border,borderRadius:BorderRadius.circular(10.r)),child:Icon(Icons.add_rounded,color:Colors.white,size:20.sp)))])]))])))));}}
class _CartBar extends StatelessWidget{final List<Map<String,dynamic>> items;final VoidCallback onTap;const _CartBar({required this.items,required this.onTap});@override Widget build(BuildContext context){final count=items.fold<int>(0,(s,i)=>s+(int.tryParse(i['quantity']?.toString()??'1')??1));final total=CartManager.subtotal;return Container(padding:EdgeInsets.fromLTRB(16.w,10.h,16.w,12.h),color:Colors.white,child:SafeArea(top:false,child:SizedBox(height:52.h,child:ElevatedButton(onPressed:onTap,style:ElevatedButton.styleFrom(backgroundColor:AppColors.primary,foregroundColor:Colors.white),child:Row(children:[Text('$count'),const Spacer(),const Text('عرض السلة'),const Spacer(),Text('${total.toStringAsFixed(0)} ج')])))));}}
class _SmartImage extends StatelessWidget{final String image;const _SmartImage({required this.image});@override Widget build(BuildContext context){final c=image.trim();if(c.isEmpty)return _fallback();if(c.startsWith('http'))return Image.network(c,fit:BoxFit.cover,errorBuilder:(_,__,___)=>_fallback());if(c.startsWith('data:image')||c.length>250){try{final raw=c.contains(',')?c.split(',').last:c;return Image.memory(base64Decode(raw),fit:BoxFit.cover,errorBuilder:(_,__,___)=>_fallback());}catch(_){return _fallback();}}return Image.asset(c,fit:BoxFit.cover,errorBuilder:(_,__,___)=>_fallback());}Widget _fallback()=>Container(color:AppColors.lightGrey,alignment:Alignment.center,child:const Icon(Icons.image_outlined,color:AppColors.textSecondary));}
